Class AnimatedSodaCan : TIStringAnimator {
    [Int]$DrawRow
    [Int]$DrawColumn
    
    AnimatedSodaCan() : base() {
        $this.DrawRow    = 1
        $this.DrawColumn = 1
    }
    
    AnimatedSodaCan(
        [TIString[]]$Frames,
        [Int]$Fps,
        [Int]$DrawRow,
        [Int]$DrawColumn
    ) : base(
        $Frames,
        $Fps
    ) {
        $this.DrawRow    = $DrawRow
        $this.DrawColumn = $DrawColumn
    }
    
    [String]GetAmendedFrame() {
        Return "`e[$($this.DrawRow);$($this.DrawColumn)H$($this.GetCurrentFrame())"
    }
}

