Class GSAnimatedSodaCanTestScreen : SMState {
    [List[AnimatedSodaCan]]$SodaCans

    GSAnimatedSodaCanTestScreen() : base('GSAnimatedSodaCanTestScreen') {
        $this.SodaCans = [List[AnimatedSodaCan]]::new()

        $this.SodaCans.Add([SodaCanLightBlueBubbles]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowLightGreen]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowDarkPink]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowLightBlue]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowLightOrange]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowPalePink]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanArrowLightGold]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanRedCherry]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanGreenApple]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanOrange]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanBigOrange]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanGreenMale]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanGreenFemale]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanGreenGatorade]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanBlueGatorade]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanRedBlueS]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanLemonLime]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanRedMultiHearts]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanPurpleMultiHearts]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanBurgundyCola]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanNotPepsi]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanOrangeFox]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanPinkEye]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanCherryBlossom]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanCoffeeBean]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanCoffeeLight]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanCoffeeDark]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanBlueGreenVolt]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanDarkRedGreenVolt]::new()) | Out-Null
        $this.SodaCans.Add([SodaCanLightRedGreenVolt]::new()) | Out-Null

        $this.OnEnter = {
            Param(
                [Context]$Context
            )

            Confirm-Context $Context

            Clear-Host
        }

        $this.OnExit = {
            Param(
                [Context]$Context
            )

            Confirm-Context $Context

            Clear-Host
        }

        $this.OnUpdate = {
            Param(
                [Context]$Context
            )

            Confirm-Context $Context

            # CONTEXT LAYOUT HERE IS
            # 0 - DELTA TIME
            # 1 - KEYS PRESSED
            # 2 - ELDORIA CORE
            Write-Host "$([ATControlSequences]::DrawOptimizeOn)" -NoNewline

            Foreach($Can in $Context.References[2].GameState.States[$Context.References[2].GameState.CurrentState].SodaCans) {
                $Can.Update($Context.References[0])
                Write-Host "$($Can.GetAmendedFrame())"
            }

            Write-Host "$([ATControlSequences]::DrawOptimizeOff)" -NoNewline
        }
    }
}
